    internal sealed class PostgreSqlEconomyStore
    {
        private static readonly ConcurrentDictionary<string, object> s_locks = new(StringComparer.Ordinal);
        internal string ConnectionString { get; }
        internal object SyncRoot { get; }
        internal PostgreSqlEconomyStore(string value)
        {
            if (String.IsNullOrWhiteSpace(value)) throw new ArgumentException("An economy database connection string is required", nameof(value));
            ConnectionString = new NpgsqlConnectionStringBuilder(value).ConnectionString;
            SyncRoot = s_locks.GetOrAdd(ConnectionString, _ => new object());
        }
        internal NpgsqlConnection Open() { NpgsqlConnection c = new(ConnectionString); c.Open(); return c; }
        internal void EnsureSchema() { using NpgsqlConnection c = Open(); EconomySchemaResources.Apply(c, EconomyStorageProvider.PostgreSql); }
        internal void ValidateSchema() { using NpgsqlConnection c = Open(); using NpgsqlCommand q = c.CreateCommand(); q.CommandText = "SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=current_schema() AND table_name=ANY(@names)"; q.Parameters.AddWithValue("names", new[] { "continuum_economy_accounts", "continuum_economy_operations", "continuum_economy_transactions", "continuum_economy_adjustments", "continuum_economy_purchases", "continuum_economy_account_registrations" }); if (Convert.ToInt32(q.ExecuteScalar(), CultureInfo.InvariantCulture) != 6) throw new InvalidOperationException("ContinuumEconomy PostgreSQL schema validation failed"); }
        internal static void Add(NpgsqlCommand q, string n, object v) => q.Parameters.AddWithValue(n, v ?? DBNull.Value);
    }

