        public LedgerTransferResult Transfer(LedgerTransferRequest r)
        {
            if (r == null || r.TransactionID == Guid.Empty || r.SenderID == Guid.Empty || r.ReceiverID == Guid.Empty || r.SenderID == r.ReceiverID || r.Amount <= 0 || (r.Description?.Length ?? 0) > 255) return TR(r?.TransactionID ?? Guid.Empty, LedgerResultCode.InvalidRequest, 0, 0, "Invalid transfer request");
