            using (NpgsqlCommand q = c.CreateCommand()) { q.CommandText = "SELECT transaction_id,sender_id,receiver_id,amount,transaction_type,region_id,object_id,description,status,sender_balance,receiver_balance,failure_reason,created_utc FROM continuum_economy_transactions WHERE(sender_id=@id OR receiver_id=@id)AND(CAST(@before AS timestamptz) IS NULL OR created_utc<@before)ORDER BY created_utc DESC,transaction_id DESC LIMIT @limit"; Add(q, "id", id); Add(q, "before", before.HasValue ? before.Value.ToUniversalTime() : DBNull.Value); Add(q, "limit", limit); using NpgsqlDataReader r = q.ExecuteReader(); while (r.Read()) { Guid from = r.GetGuid(1), to = r.GetGuid(2); bool credit = to == id; list.Add(new() { TransactionID = r.GetGuid(0), AccountID = id, CounterpartyID = credit ? from : to, Amount = r.GetInt64(3), TransactionType = r.GetInt32(4), RegionID = r.GetGuid(5), ObjectID = r.GetGuid(6), Description = r.GetString(7), Succeeded = r.GetInt16(8) == 1, ResultingBalance = credit ? r.GetInt64(10) : r.GetInt64(9), FailureReason = r.GetString(11), CreatedUtc = r.GetDateTime(12).ToUniversalTime(), IsCredit = credit }); } }
