            list.Sort((a, b) => { int x = b.CreatedUtc.CompareTo(a.CreatedUtc); return x != 0 ? x : b.TransactionID.CompareTo(a.TransactionID); }); if (list.Count > limit) list.RemoveRange(limit, list.Count - limit); return list;
        }
