        public LedgerPurchaseResult Authorize(LedgerPurchaseRequest r) { if (r == null || r.PurchaseID == Guid.Empty || r.BuyerID == Guid.Empty || r.SellerID == Guid.Empty || r.BuyerID == r.SellerID || r.Amount <= 0 || (r.Description?.Length ?? 0) > 255) return R(r?.PurchaseID ?? Guid.Empty, LedgerResultCode.InvalidRequest, 0, 0, 0, 0, "Invalid purchase request"); string h = PostgreSqlEconomyLedger.Hash(String.Join("|", r.BuyerID, r.SellerID, r.Amount.ToString(CultureInfo.InvariantCulture), r.TransactionType, r.RegionID, r.ObjectID, r.Description ?? String.Empty)); using NpgsqlConnection c = s.Open(); using NpgsqlTransaction t = c.BeginTransaction(IsolationLevel.Serializable); Row prior = Read(c, t, r.PurchaseID); if (prior != null) { t.Commit(); return !String.Equals(prior.Hash, h, StringComparison.Ordinal) ? R(r.PurchaseID, LedgerResultCode.TransactionConflict, prior.State, 0, 0, 0, "Purchase ID conflict") : R(r.PurchaseID, LedgerResultCode.Replayed, prior.State, prior.BuyerBalance, prior.BuyerBalance, prior.SellerBalance, "Purchase already recorded"); } PostgreSqlEconomyLedger.Ensure(c, t, r.BuyerID); PostgreSqlEconomyLedger.Ensure(c, t, r.SellerID); PostgreSqlEconomyLedger.Lock(c, t, r.BuyerID, r.SellerID); long bb = PostgreSqlEconomyLedger.Balance(c, t, r.BuyerID), sb = PostgreSqlEconomyLedger.Balance(c, t, r.SellerID), held = PostgreSqlEconomyLedger.Held(c, t, r.BuyerID); int state = bb - held < r.Amount ? 4 : 1; string f = state == 1 ? String.Empty : "Insufficient funds"; using (NpgsqlCommand q = c.CreateCommand()) { q.Transaction = t; q.CommandText = "INSERT INTO continuum_economy_operations(operation_id,request_hash,operation_kind)VALUES(@id,@h,3);INSERT INTO continuum_economy_purchases(purchase_id,request_hash,buyer_id,seller_id,amount,transaction_type,region_id,object_id,description,state,buyer_balance,seller_balance,failure_reason)VALUES(@id,@h,@buyer,@seller,@amount,@type,@region,@object,@description,@state,@bb,@sb,@failure)"; object[] v = { r.PurchaseID, h, r.BuyerID, r.SellerID, r.Amount, r.TransactionType, r.RegionID, r.ObjectID, r.Description ?? String.Empty, (short)state, bb, sb, f }; string[] n = { "id", "h", "buyer", "seller", "amount", "type", "region", "object", "description", "state", "bb", "sb", "failure" }; for (int i = 0; i < n.Length; i++) PostgreSqlEconomyLedger.Add(q, n[i], v[i]); q.ExecuteNonQuery(); } t.Commit(); return R(r.PurchaseID, state == 1 ? LedgerResultCode.Committed : LedgerResultCode.InsufficientFunds, state, bb, bb - held - (state == 1 ? r.Amount : 0), sb, state == 1 ? "Purchase authorized" : f); }
        public LedgerPurchaseResult Capture(Guid id, Guid buyer) => Complete(id, buyer, true); public LedgerPurchaseResult Cancel(Guid id, Guid buyer) => Complete(id, buyer, false);
        private LedgerPurchaseResult Complete(Guid id, Guid expected, bool capture) { if (id == Guid.Empty || expected == Guid.Empty) return R(id, LedgerResultCode.InvalidRequest, 0, 0, 0, 0, "Invalid purchase completion request"); using NpgsqlConnection c = s.Open(); using NpgsqlTransaction t = c.BeginTransaction(IsolationLevel.Serializable); Row r = Read(c, t, id, true); if (r == null) { t.Commit(); return R(id, LedgerResultCode.InvalidRequest, 0, 0, 0, 0, "Purchase not found"); } if (r.Buyer != expected) { t.Commit(); return R(id, LedgerResultCode.InvalidRequest, r.State, r.BuyerBalance, 0, r.SellerBalance, "Purchase buyer mismatch"); } int target = capture ? 2 : 3; if (r.State == target) { t.Commit(); return R(id, LedgerResultCode.Replayed, r.State, r.BuyerBalance, r.BuyerBalance, r.SellerBalance, "Purchase already completed"); } if (r.State != 1) { t.Commit(); return R(id, LedgerResultCode.InvalidRequest, r.State, r.BuyerBalance, 0, r.SellerBalance, "Purchase is not authorized"); } PostgreSqlEconomyLedger.Lock(c, t, r.Buyer, r.Seller); long bb = PostgreSqlEconomyLedger.Balance(c, t, r.Buyer), sb = PostgreSqlEconomyLedger.Balance(c, t, r.Seller); if (capture) { long priorBuyer = bb, priorSeller = sb; try { checked { bb -= r.Amount; sb += r.Amount; } } catch (OverflowException) { t.Rollback(); return R(id, LedgerResultCode.InvalidRequest, r.State, priorBuyer, 0, priorSeller, "The purchase exceeds the supported balance range"); } PostgreSqlEconomyLedger.Set(c, t, r.Buyer, bb); PostgreSqlEconomyLedger.Set(c, t, r.Seller, sb); using NpgsqlCommand tx = c.CreateCommand(); tx.Transaction = t; tx.CommandText = "INSERT INTO continuum_economy_transactions(transaction_id,request_hash,sender_id,receiver_id,amount,transaction_type,region_id,object_id,description,status,sender_balance,receiver_balance)VALUES(@id,@h,@buyer,@seller,@amount,@type,@region,@object,@description,1,@bb,@sb)"; object[] v = { r.ID, r.Hash, r.Buyer, r.Seller, r.Amount, r.Type, r.Region, r.Object, r.Description, bb, sb }; string[] n = { "id", "h", "buyer", "seller", "amount", "type", "region", "object", "description", "bb", "sb" }; for (int i = 0; i < n.Length; i++) PostgreSqlEconomyLedger.Add(tx, n[i], v[i]); tx.ExecuteNonQuery(); } using (NpgsqlCommand q = c.CreateCommand()) { q.Transaction = t; q.CommandText = "UPDATE continuum_economy_purchases SET state=@state,buyer_balance=@bb,seller_balance=@sb,completed_utc=CURRENT_TIMESTAMP WHERE purchase_id=@id AND state=1"; PostgreSqlEconomyLedger.Add(q, "state", (short)target); PostgreSqlEconomyLedger.Add(q, "bb", bb); PostgreSqlEconomyLedger.Add(q, "sb", sb); PostgreSqlEconomyLedger.Add(q, "id", id); if (q.ExecuteNonQuery() != 1) throw new InvalidOperationException("Purchase state changed concurrently"); } t.Commit(); return R(id, LedgerResultCode.Committed, target, bb, bb, sb, capture ? "Purchase captured" : "Purchase cancelled"); }
        public IReadOnlyList<LedgerPendingPurchase> GetPending(DateTime before, int limit) { limit = Math.Clamp(limit, 1, 500); List<LedgerPendingPurchase> list = new(); using NpgsqlConnection c = s.Open(); using NpgsqlCommand q = c.CreateCommand(); q.CommandText = "SELECT purchase_id,buyer_id,seller_id,amount,transaction_type,region_id,object_id,description,created_utc FROM continuum_economy_purchases WHERE state=1 AND created_utc<@before ORDER BY created_utc LIMIT @limit"; PostgreSqlEconomyLedger.Add(q, "before", before.ToUniversalTime()); PostgreSqlEconomyLedger.Add(q, "limit", limit); using NpgsqlDataReader r = q.ExecuteReader(); while (r.Read()) list.Add(new() { PurchaseID = r.GetGuid(0), BuyerID = r.GetGuid(1), SellerID = r.GetGuid(2), Amount = r.GetInt64(3), TransactionType = r.GetInt32(4), RegionID = r.GetGuid(5), ObjectID = r.GetGuid(6), Description = r.GetString(7), CreatedUtc = r.GetDateTime(8).ToUniversalTime() }); return list; }
        private sealed class Row { public Guid ID, Buyer, Seller, Region, Object; public string Hash, Description; public long Amount, BuyerBalance, SellerBalance; public int Type, State; }
        private static Row Read(NpgsqlConnection c, NpgsqlTransaction t, Guid id, bool update = false) { using NpgsqlCommand q = c.CreateCommand(); q.Transaction = t; q.CommandText = "SELECT request_hash,buyer_id,seller_id,amount,transaction_type,region_id,object_id,description,state,buyer_balance,seller_balance FROM continuum_economy_purchases WHERE purchase_id=@id" + (update ? " FOR UPDATE" : String.Empty); PostgreSqlEconomyLedger.Add(q, "id", id); using NpgsqlDataReader r = q.ExecuteReader(); return r.Read() ? new() { ID = id, Hash = r.GetString(0).Trim(), Buyer = r.GetGuid(1), Seller = r.GetGuid(2), Amount = r.GetInt64(3), Type = r.GetInt32(4), Region = r.GetGuid(5), Object = r.GetGuid(6), Description = r.GetString(7), State = r.GetInt16(8), BuyerBalance = r.GetInt64(9), SellerBalance = r.GetInt64(10) } : null; }
        private static LedgerPurchaseResult R(Guid id, LedgerResultCode code, int state, long bb, long available, long sb, string m) => new() { PurchaseID = id, Code = code, State = (LedgerPurchaseState)state, BuyerBalance = bb, BuyerAvailableBalance = available, SellerBalance = sb, Message = m };
    }

    public sealed class PostgreSqlEconomyAccountService : IEconomyAccountService
    {
        private readonly PostgreSqlEconomyStore s; public PostgreSqlEconomyAccountService(string cs) { s = new(cs); }
        internal PostgreSqlEconomyAccountService(PostgreSqlEconomyStore store) { s = store; }
        public LedgerResultCode Register(LedgerAccountRegistrationRequest r, out string message) { if (r == null || r.OperationID == Guid.Empty || r.AccountID == Guid.Empty || r.ActorID == Guid.Empty || (r.AccountType != LedgerAccountType.Group && r.AccountType != LedgerAccountType.System) || String.IsNullOrWhiteSpace(r.DisplayName) || r.DisplayName.Length > 255) { message = "Valid operation, account, actor, non-resident type and display name are required"; return LedgerResultCode.InvalidRequest; } string h = PostgreSqlEconomyLedger.Hash(String.Join("|", r.AccountID, r.ActorID, (int)r.AccountType, r.DisplayName.Trim())); using NpgsqlConnection c = s.Open(); using NpgsqlTransaction t = c.BeginTransaction(IsolationLevel.Serializable); using (NpgsqlCommand prior = c.CreateCommand()) { prior.Transaction = t; prior.CommandText = "SELECT request_hash FROM continuum_economy_account_registrations WHERE operation_id=@id"; PostgreSqlEconomyLedger.Add(prior, "id", r.OperationID); object v = prior.ExecuteScalar(); if (v != null) { t.Commit(); if (!String.Equals(Convert.ToString(v)?.Trim(), h, StringComparison.Ordinal)) { message = "The operation ID is already associated with different registration data"; return LedgerResultCode.TransactionConflict; } message = "Economy account already registered"; return LedgerResultCode.Replayed; } } int? existing = null; using (NpgsqlCommand q = c.CreateCommand()) { q.Transaction = t; q.CommandText = "SELECT account_type FROM continuum_economy_accounts WHERE account_id=@id FOR UPDATE"; PostgreSqlEconomyLedger.Add(q, "id", r.AccountID); object v = q.ExecuteScalar(); if (v != null) existing = Convert.ToInt32(v); } if (existing.HasValue && existing.Value != (int)r.AccountType) { t.Rollback(); message = "The UUID already belongs to a different economy account class"; return LedgerResultCode.TransactionConflict; } using (NpgsqlCommand q = c.CreateCommand()) { q.Transaction = t; q.CommandText = "INSERT INTO continuum_economy_accounts(account_id,balance,account_type)VALUES(@account,0,@type)ON CONFLICT(account_id)DO NOTHING;INSERT INTO continuum_economy_operations(operation_id,request_hash,operation_kind)VALUES(@operation,@hash,4);INSERT INTO continuum_economy_account_registrations(operation_id,request_hash,account_id,actor_id,account_type,display_name)VALUES(@operation,@hash,@account,@actor,@type,@name)"; PostgreSqlEconomyLedger.Add(q, "account", r.AccountID); PostgreSqlEconomyLedger.Add(q, "type", (short)r.AccountType); PostgreSqlEconomyLedger.Add(q, "operation", r.OperationID); PostgreSqlEconomyLedger.Add(q, "hash", h); PostgreSqlEconomyLedger.Add(q, "actor", r.ActorID); PostgreSqlEconomyLedger.Add(q, "name", r.DisplayName.Trim()); q.ExecuteNonQuery(); } t.Commit(); message = "Economy account registered"; return LedgerResultCode.Committed; }
    }
}
